/** A semantic token's value: exactly one `{dotted.path}` reference. */
export const ALIAS = /^\{([^{}]+)\}$/;

/** Prefix of every CSS variable the compiler emits. */
export const CSS_VAR_PREFIX = '--st-';

/** Namespaces whose Tailwind defaults are wiped, so only semantic roles can generate utilities. */
export const RESET = [
  '--color-*',
  '--font-*',
  '--text-*',
  '--spacing-*',
  '--radius-*',
  '--shadow-*',
  '--inset-shadow-*',
  '--drop-shadow-*',
] as const;

export const HEADER_COMMENT =
  '/* Generated by packages/tokens/scripts/generate.ts from the *.tokens.json files. Do not edit. */';

export const THEME_COMMENT =
  '/* Only semantic roles become Tailwind utilities; the default palette and scales are removed. */';

export const FOCUS_RING_LINES = [
  '/* The one focus style: components use `focus-ring` (outside the control) or `focus-ring-inset` (inside it, when the edge is clipped). */',
  '@utility focus-ring {',
  '  &:focus-visible {',
  '    outline: 2px solid var(--st-color-focus);',
  '    outline-offset: 2px;',
  '  }',
  '}',
  '',
  '@utility focus-ring-inset {',
  '  &:focus-visible {',
  '    outline: 2px solid var(--st-color-focus);',
  '    outline-offset: -2px;',
  '  }',
  '}',
];

